function output = heartlib(a, b, c)
% output = heartlib(a, b, c)
%
%    s_f = (a_f+b_f+c_f)/2
%    A_f = sqrt(s_f (s_f-a_f) (s_f-b_f) (s_f-c_f))
%    C_f = 1/(8 A_f) [b_f²+c_f²-a_f², c_f²+a_f²-b_f², a_f²+b_f²-c_f²]
%    
%    where
%    
%    a_i ∈ ℝ
%    b_i ∈ ℝ
%    c_i ∈ ℝ
%    
    a = reshape(a,[],1);
    b = reshape(b,[],1);
    c = reshape(c,[],1);

    dim_0 = size(a, 1);
    assert( size(a,1) == dim_0 );
    assert( size(b,1) == dim_0 );
    assert( size(c,1) == dim_0 );

    % s_f = (a_f+b_f+c_f)/2

    s = zeros(dim_0,1);
    for f = 1:dim_0
        s(f) = (a(f) + b(f) + c(f)) / 2;
    end
    % A_f = sqrt(s_f (s_f-a_f) (s_f-b_f) (s_f-c_f))

    A = zeros(dim_0,1);
    for f = 1:dim_0
        A(f) = sqrt(s(f) * (s(f) - a(f)) * (s(f) - b(f)) * (s(f) - c(f)));
    end
    % C_f = 1/(8 A_f) [b_f²+c_f²-a_f², c_f²+a_f²-b_f², a_f²+b_f²-c_f²]

    C = zeros(dim_0, 1, 3);
    for f = 1:dim_0
        C_f_0 = zeros(1, 3);
        C_f_0(1,:) = [b(f).^2 + c(f).^2 - a(f).^2, c(f).^2 + a(f).^2 - b(f).^2, a(f).^2 + b(f).^2 - c(f).^2];
        squeeze(C(f,:,:)) = 1 / (8 * A(f)) * C_f_0;
    end
    output.s = s;
    output.A = A;
    output.C = C;
end

